public sealed class OpenPoolTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static string Stream => OpenPoolState.StreamKey(SeedData.PoolId.ToString());

    // A pool is opened with a fixed capacity
    //   GIVEN (nothing)
    //   WHEN  OpenPool(capacity=3)
    //   THEN  Pool Opened(capacity=3)
    [Fact]
    public async Task APoolIsOpenedWithAFixedCapacity()
    {
        await WhenPosting(x =>
        {
            x.Post.Json(new OpenPool(SeedData.PoolId, 3)).ToUrl(OpenPoolEndpoint.Route);
            x.StatusCodeShouldBe(200);
        });

        var events = await EventsFor(Stream);
        events.ShouldHaveSingleItem().ShouldBeOfType<PoolOpened>().Capacity.ShouldBe(3);
    }

    // A pool with no capacity is refused
    //   GIVEN (nothing)
    //   WHEN  OpenPool(capacity=0)
    //   THEN  error: CapacityMustBePositive
    //   No GIVEN, so this is a periphery rule: expect 400 from the validator.
    [Fact]
    public async Task APoolWithNoCapacityIsRefused()
    {
        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(new OpenPool(SeedData.PoolId, 0)).ToUrl(OpenPoolEndpoint.Route);
            x.StatusCodeShouldBe(400);
        });

        // The rule NAME is the outcome, and Wolverine.HTTP puts a FluentValidation failure in the
        // ProblemDetails body — so then="error: CapacityMustBePositive" asserts the same string whether the
        // rule was caught at the periphery or inside a decider.
        (await result.ReadAsTextAsync()).ShouldContain("CapacityMustBePositive");

        // AND NOTHING WAS APPENDED. Without this the test passes against a system that rejects the request
        // after opening the pool, which is the failure a status-code assertion cannot see.
        (await EventsFor(Stream)).ShouldBeEmpty();
    }
}
